Cet exemple Java montre une structure de service et de référentiel.

```java
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.stream.Collectors;

record Expense(long id, String title, String category, double amount) {}

final class ExpenseRepository {
    private final List<Expense> expenses = new ArrayList<>();
    void add(Expense expense) { expenses.add(expense); }
    void remove(long id) { expenses.removeIf(item -> item.id() == id); }
    List<Expense> findAll() { return List.copyOf(expenses); }
}

final class ExpenseService {
    private final ExpenseRepository repository;
    ExpenseService(ExpenseRepository repository) { this.repository = repository; }
    Map<String, Double> totalsByCategory() {
        return repository.findAll().stream().collect(Collectors.groupingBy(
            Expense::category, Collectors.summingDouble(Expense::amount)));
    }
}

public class SmartSpend {
    public static void main(String[] args) {
        ExpenseRepository repository = new ExpenseRepository();
        repository.add(new Expense(1, "Lunch", "Food", 12.5));
        repository.add(new Expense(2, "Bus", "Transport", 2.0));
        ExpenseService service = new ExpenseService(repository);
        service.totalsByCategory().forEach((category, total) ->
            System.out.println(category + ": " + total));
    }
}
```

Voici un exemple C plus long.

```c
#include <stdio.h>

#define MAX_EXPENSES 32

typedef struct {
    char title[64];
    char category[32];
    double amount;
} Expense;

double total(const Expense expenses[], size_t count) {
    double result = 0.0;
    for (size_t i = 0; i < count; ++i) result += expenses[i].amount;
    return result;
}

int main(void) {
    Expense expenses[MAX_EXPENSES] = {
        {"Lunch", "Food", 12.5},
        {"Bus", "Transport", 2.0}
    };
    printf("Total: %.2f\n", total(expenses, 2));
    return 0;
}
```

